using SobhanNotificationHub.Models;namespace SobhanNotificationHub.Services;public sealed class PollingWorker:IDisposable{private readonly AppServices _services;private readonly CancellationToken _appToken;private CancellationTokenSource? _local;private Task? _task;public PollingWorker(AppServices services,CancellationToken token){_services=services;_appToken=token;}public void Start(){_local=CancellationTokenSource.CreateLinkedTokenSource(_appToken);_task=RunAsync(_local.Token);LoggingService.Info("polling_start");}public static async Task<int> PollOnceAsync(AppServices services,CancellationToken ct){var since=await services.Cache.LastIdAsync();var result=await services.Api.GetPendingAsync(since,services.CurrentConfig?.Client.MaxNotificationsPerPoll??20,ct);foreach(var item in result.Items.OrderByDescending(Priority)){if(await services.Cache.ExistsAsync(item.Id))continue;await services.Cache.SaveAsync(item);await services.Notifier.ShowAsync(item,services.CurrentConfig!,ct);await services.Api.AckAsync(item.Id,"delivered",ct);await services.Cache.MarkAckedAsync(item.Id);}return Math.Clamp(result.NextPoll,10,300);}private async Task RunAsync(CancellationToken ct){var failures=0;while(!ct.IsCancellationRequested){var delay=_services.CurrentConfig?.Client.PollSeconds??20;try{delay=await PollOnceAsync(_services,ct);failures=0;_services.Tray.SetConnected(_services.CurrentConfig?.User.DisplayName??"");}catch(DeviceUnauthorizedException){LoggingService.Info("token_invalid");_services.TokenStore.Clear();_services.Tray.SetDisconnected();System.Windows.Application.Current.Dispatcher.Invoke(()=>new UI.DeviceConnectWindow().Show());return;}catch(OperationCanceledException)when(ct.IsCancellationRequested){return;}catch(Exception ex){failures++;delay=failures switch{1=>30,2=>60,_=>120};LoggingService.Error("polling",ex);_services.Tray.SetWarning();}await Task.Delay(TimeSpan.FromSeconds(delay),ct);}}private static int Priority(SobhanNotification n)=>n.Priority switch{"important"=>3,"normal"=>2,"low"=>1,_=>2};public void Dispose(){_local?.Cancel();try{_task?.Wait(1000);}catch{}LoggingService.Info("polling_stop");_local?.Dispose();}}
